import kotlinx.coroutines.*

fun main() = runBlocking {
    val a = launch { delay(10) }
    a.invokeOnCompletion { println("a: $it") }
    val b = launch { delay(1_000) }
    b.invokeOnCompletion { cause ->
        println("b: ${cause is CancellationException}")
    }
    delay(50)
    b.cancel()
    joinAll(a, b)
    println("done")
}

